import React, { useState, useEffect, useRef } from "react";

/* ============================================================
   TOMI — capa 1: estructura visual, navegación y onboarding
   Datos simulados. Sin IA real, sin visión por computadora, sin pagos.
   ============================================================ */

/* ---------------- Tokens de diseño (clases CSS propias) ---------------- */
function TomiStyles() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Nunito+Sans:wght@400;600;700;800&display=swap');

      .tomi-root { font-family: 'Nunito Sans', sans-serif; color: #3D2B22; }
      .tomi-display { font-family: 'Baloo 2', sans-serif; }

      .tomi-bg-cream { background-color: #FFF6EA; }
      .tomi-bg-page { background-color: #EFEAE0; }
      .tomi-bg-tomato { background-color: #E85A3B; }
      .tomi-bg-tomato-deep { background-color: #C23E28; }
      .tomi-bg-tomato-soft { background-color: #FBDCCE; }
      .tomi-bg-leaf { background-color: #6E9B47; }
      .tomi-bg-leaf-soft { background-color: #E3EDD7; }
      .tomi-bg-gold { background-color: #F2A93B; }
      .tomi-bg-gold-soft { background-color: #FCEACA; }
      .tomi-bg-white { background-color: #FFFFFF; }

      .tomi-text-tomato { color: #E85A3B; }
      .tomi-text-tomato-deep { color: #C23E28; }
      .tomi-text-leaf { color: #4C7A2E; }
      .tomi-text-gold { color: #B9791C; }
      .tomi-text-ink { color: #3D2B22; }
      .tomi-text-ink-soft { color: #8A7669; }

      .tomi-border-tomato { border-color: #E85A3B; }
      .tomi-border-soft { border-color: #EADFCF; }

      .tomi-shadow-tomato { box-shadow: 0 14px 30px -10px rgba(232,90,59,0.35); }
      .tomi-shadow-soft { box-shadow: 0 8px 20px -8px rgba(61,43,34,0.15); }
      .tomi-shadow-card { box-shadow: 0 6px 16px -6px rgba(61,43,34,0.12); }

      .tomi-chip {
        border: 2px solid #EADFCF;
        background: #FFFFFF;
        transition: all 0.15s ease;
      }
      .tomi-chip-active {
        border: 2px solid #E85A3B;
        background: #FBDCCE;
      }

      .tomi-btn-primary {
        background: #E85A3B;
        color: #FFF8F2;
      }
      .tomi-btn-primary:active { background: #C23E28; }
      .tomi-btn-primary:disabled { background: #E8C9BC; color: #FFF8F2; }

      .tomi-tap { transition: transform 0.12s ease; }
      .tomi-tap:active { transform: scale(0.96); }

      .tomi-scroll::-webkit-scrollbar { display: none; }
      .tomi-scroll { -ms-overflow-style: none; scrollbar-width: none; }

      @keyframes tomiSplashIn {
        0% { transform: translateY(60px) scale(0.5); opacity: 0; }
        55% { transform: translateY(-14px) scale(1.06); opacity: 1; }
        75% { transform: translateY(4px) scale(0.98); }
        100% { transform: translateY(0) scale(1); }
      }
      .tomi-splash-in { animation: tomiSplashIn 0.8s cubic-bezier(.2,.8,.3,1.2) both; }
      @keyframes tomiSway { 0%, 100% { transform: rotate(-4deg); } 50% { transform: rotate(4deg); } }
      .tomi-sway { animation: tomiSway 1.1s ease-in-out infinite; transform-origin: 50% 90%; }
      @keyframes tomiSparkle {
        0% { transform: scale(0) rotate(0deg); opacity: 0; }
        40% { transform: scale(1.2) rotate(40deg); opacity: 1; }
        100% { transform: scale(0.6) rotate(90deg); opacity: 0; }
      }
      .tomi-sparkle { position: absolute; animation: tomiSparkle 1.2s ease-out infinite; }
      @keyframes tomiFadeUp { from { transform: translateY(14px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
      .tomi-fade-up { animation: tomiFadeUp 0.5s ease both; }
      @keyframes tomiSheetUp { from { transform: translateY(100%); } to { transform: translateY(0); } }
      .tomi-sheet-up { animation: tomiSheetUp 0.55s cubic-bezier(.2,.8,.2,1) 0.15s both; }
      @keyframes tomiSplashOut { to { opacity: 0; transform: scale(1.04); } }
      .tomi-splash-out { animation: tomiSplashOut 0.3s ease forwards; }

      @keyframes tomiBlink { 0%, 94%, 100% { transform: scaleY(1); } 97% { transform: scaleY(0.12); } }
      .tomi-blink { animation: tomiBlink 4.2s infinite; transform-origin: center; }

      @keyframes tomiBounce { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
      .tomi-bounce { animation: tomiBounce 2.4s ease-in-out infinite; }

      @keyframes tomiArm { 0%, 100% { transform: rotate(0deg); } 50% { transform: rotate(-8deg); } }
      .tomi-arm { animation: tomiArm 1.8s ease-in-out infinite; transform-origin: 140px 190px; }

      @keyframes tomiPopIn {
        0% { opacity: 0; transform: translateY(10px) scale(0.9); }
        100% { opacity: 1; transform: translateY(0) scale(1); }
      }
      .tomi-pop-in { animation: tomiPopIn 0.35s ease both; }

      @keyframes tomiCelebrate {
        0% { transform: scale(0.7); opacity: 0; }
        60% { transform: scale(1.08); opacity: 1; }
        100% { transform: scale(1); opacity: 1; }
      }
      .tomi-celebrate { animation: tomiCelebrate 0.5s ease both; }

      @keyframes tomiPulseSoft {
        0%, 100% { opacity: 1; }
        50% { opacity: 0.55; }
      }
      .tomi-pulse { animation: tomiPulseSoft 1.1s ease-in-out infinite; }

      @keyframes tomiShutter {
        0% { transform: scale(1); }
        30% { transform: scale(0.85); }
        100% { transform: scale(1); }
      }
      .tomi-shutter { animation: tomiShutter 0.25s ease; }

      @keyframes tomiConfettiFall {
        0% { transform: translateY(-20px) rotate(0deg); opacity: 1; }
        100% { transform: translateY(340px) rotate(200deg); opacity: 0; }
      }
      .tomi-confetti-piece { position: absolute; top: 0; animation: tomiConfettiFall 2.2s ease-in forwards; }
    `}</style>
  );
}

/* ---------------- Mascota: Tomi ---------------- */

/* Identidad visual oficial de Tomi (Fase 1 del rediseño).
   Ya NO se dibuja con SVG: se usan assets de imagen reales, recortados y
   preparados a partir de la hoja de personaje aprobada como referencia
   oficial. Cada pose es una imagen propia del MISMO personaje — no una
   reinterpretación.

   Por tamaño del archivo, aquí solo se incrustan (como data URI, sin
   depender de ningún hosting externo) las poses que algún punto de la
   app ya usa hoy. El resto de las 23 poses recortadas de la hoja de
   referencia (ej. "Sosteniendo un plato", "Con gorro de chef", "Gourmet",
   "Saludable", "Deportista", "Batidos", "Con ingredientes", "En la
   cocina", "Triste", "Enojado (juguetón)") quedan guardadas en
   /assets/tomi/ como archivos, listas para incorporarse en próximas
   fases sin volver a tocar este bloque. */

const TOMI_IMG_HAPPY = "data:image/webp;base64,";
const TOMI_IMG_THINKING = "data:image/webp;base64,";
const TOMI_IMG_WAVE = "data:image/webp;base64,";
const TOMI_IMG_CURIOUS = "data:image/webp;base64,";
const TOMI_IMG_PROUD = "data:image/webp;base64,";
const TOMI_IMG_CELEBRATING = "data:image/webp;base64,";
const TOMI_IMG_SURPRISED = "data:image/webp;base64,";
const TOMI_IMG_CALM = "data:image/webp;base64,";
const TOMI_IMG_LOVING = "data:image/webp;base64,";
const TOMI_IMG_COOKING = "data:image/webp;base64,";
const TOMI_IMG_SAVINGS_MODE = "data:image/webp;base64,";
const TOMI_IMG_EXCITED = "data:image/webp;base64,";
const TOMI_IMG_EXPLAINING = "data:image/webp;base64,";

/* Mapa único de pose → imagen real de Tomi. Punto central de verdad:
   agregar una pose nueva en el futuro es agregar una línea aquí. */
const TOMI_IMAGE_MAP = {
  happy: TOMI_IMG_HAPPY,
  thinking: TOMI_IMG_THINKING,
  wave: TOMI_IMG_WAVE,
  curious: TOMI_IMG_CURIOUS,
  proud: TOMI_IMG_PROUD,
  celebrating: TOMI_IMG_CELEBRATING,
  surprised: TOMI_IMG_SURPRISED,
  calm: TOMI_IMG_CALM,
  loving: TOMI_IMG_LOVING,
  cooking: TOMI_IMG_COOKING,
  saving: TOMI_IMG_SAVINGS_MODE,
  excited: TOMI_IMG_EXCITED,
  explaining: TOMI_IMG_EXPLAINING,
  // Alias hacia las mismas imágenes de arriba, para las poses que ya
  // usaba la app y que no tienen una ilustración 1:1 propia en la hoja
  // de referencia (se asignó la más parecida, tal como se aprobó):
  watching: TOMI_IMG_CURIOUS,
  confused: TOMI_IMG_SURPRISED,
  waiting: TOMI_IMG_CALM,
};

function resolveTomiImage(pose) {
  return TOMI_IMAGE_MAP[pose] || TOMI_IMAGE_MAP.happy;
}

/* Respaldo mínimo — nunca el dibujo SVG detallado anterior — solo por si
   una imagen no llegara a cargar (red, ruta, etc.). */
function TomiFallback({ size, round }) {
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: round ? "50%" : 18,
        background: "#F2A93B",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: Math.round(size * 0.5),
      }}
    >
      🍅
    </div>
  );
}

function handleTomiImgError(e) {
  const img = e.currentTarget;
  img.style.display = "none";
  if (img.nextSibling) img.nextSibling.style.display = "flex";
}

function TomiBody({ size = 140, pose = "happy", wave = false, animated = false }) {
  const src = resolveTomiImage(pose);
  const boxHeight = size * 1.55; // misma caja máxima que usaba el SVG, para no romper layouts existentes
  const content = (
    <div style={{ position: "relative", width: size, height: boxHeight, display: "inline-block" }}>
      <img
        src={src}
        alt="Tomi"
        onError={handleTomiImgError}
        style={{ width: "100%", height: "100%", objectFit: "contain", objectPosition: "bottom", display: "block" }}
      />
      <div style={{ display: "none", position: "absolute", inset: 0, alignItems: "center", justifyContent: "center" }}>
        <TomiFallback size={Math.round(size * 0.9)} />
      </div>
    </div>
  );
  return animated ? <div className="tomi-bounce" style={{ display: "inline-block" }}>{content}</div> : content;
}

function TomiHead({ size = 64, pose = "happy" }) {
  const src = resolveTomiImage(pose);
  return (
    <div style={{ position: "relative", width: size, height: size, display: "inline-block" }}>
      <img
        src={src}
        alt="Tomi"
        onError={handleTomiImgError}
        style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 15%", borderRadius: "50%", display: "block" }}
      />
      <div style={{ display: "none", position: "absolute", inset: 0, alignItems: "center", justifyContent: "center" }}>
        <TomiFallback size={size} round />
      </div>
    </div>
  );
}

/* ---------------- Tomi "vivo": estados reutilizables ---------------- */

/* Cada estado apunta directamente a su propia imagen (ya no a una de dos
   caras SVG + insignia). Se conservan exactamente los mismos nombres de
   pose que ya usaba la app (wave, happy, thinking, watching, proud,
   celebrating, confused, waiting, loving, cooking, saving) para no
   romper ningún llamado existente; "badge" se mantiene como pequeño
   detalle opcional encima de la imagen. */
const TOMI_POSES = {
  wave: { face: "wave", badge: null, wave: true },
  happy: { face: "happy", badge: null },
  thinking: { face: "thinking", badge: null },
  watching: { face: "watching", badge: null },
  proud: { face: "proud", badge: null },
  celebrating: { face: "celebrating", badge: "🎉" },
  confused: { face: "confused", badge: null },
  waiting: { face: "waiting", badge: null },
  loving: { face: "loving", badge: null },
  cooking: { face: "cooking", badge: null },
  saving: { face: "saving", badge: null },
  surprised: { face: "surprised", badge: null },
  excited: { face: "excited", badge: null },
  explaining: { face: "explaining", badge: "💬" },
};

function TomiAvatar({ pose = "happy", size = 110, variant = "body", animated = false, celebrate = false }) {
  const cfg = TOMI_POSES[pose] || TOMI_POSES.happy;
  const body =
    variant === "head" ? (
      <TomiHead size={size} pose={cfg.face} />
    ) : (
      <TomiBody size={size} pose={cfg.face} wave={cfg.wave} animated={animated} />
    );
  return (
    <div className={celebrate ? "tomi-celebrate" : undefined} style={{ position: "relative", display: "inline-block" }}>
      {body}
      {cfg.badge && (
        <span style={{ position: "absolute", top: variant === "head" ? -2 : 4, right: variant === "head" ? -2 : 2, fontSize: Math.round(size * 0.22) }}>
          {cfg.badge}
        </span>
      )}
    </div>
  );
}


/* ---------------- Voz de Tomi (arquitectura preparada) ---------------- */

/* Abstracción para leer los mensajes de Tomi en voz alta. Hoy usa la síntesis
   de voz del navegador si está disponible; mañana puede apuntar a un
   proveedor de TTS real sin que las pantallas que la llaman cambien. */
/* Intenta elegir, entre las voces que ya ofrece el navegador, una en
   español que suene masculina y juvenil. Si no encuentra ninguna que
   encaje, no fuerza nada: deja que el navegador use su voz por defecto. */
function pickTomiVoice() {
  try {
    if (!window.speechSynthesis) return null;
    const voices = window.speechSynthesis.getVoices();
    if (!voices || voices.length === 0) return null;
    const spanish = voices.filter((v) => v.lang && v.lang.toLowerCase().startsWith("es"));
    const pool = spanish.length > 0 ? spanish : voices;
    const maleHints = ["jorge", "diego", "pablo", "carlos", "enrique", "juan", "male", "hombre"];
    const femaleHints = ["mujer", "female", "mónica", "monica", "paulina", "helena", "lucía", "lucia", "sabina"];
    const byMaleName = pool.find((v) => maleHints.some((h) => v.name.toLowerCase().includes(h)));
    if (byMaleName) return byMaleName;
    const notFemale = pool.find((v) => !femaleHints.some((h) => v.name.toLowerCase().includes(h)));
    return notFemale || pool[0];
  } catch (e) {
    return null;
  }
}

const TOMI_COOKING_RATE = 0.86; // más lento y pausado: para el paso a paso al cocinar

function speakTomiMessage(message, voiceEnabled = true, rate = 1) {
  if (!voiceEnabled) return;
  try {
    if (typeof window !== "undefined" && window.speechSynthesis) {
      window.speechSynthesis.cancel();
      queueTomiUtterance(message, rate);
    }
  } catch (e) {
    // La voz es un extra, nunca debe romper la experiencia si falla.
  }
}

/* Lee varios textos en orden (ej. instrucción + mensaje complementario de
   Tomi) sin cortarse entre uno y otro. Reutiliza el mismo motor de voz. */
function speakTomiSequence(messages, voiceEnabled = true, rate = 1) {
  if (!voiceEnabled) return;
  try {
    if (typeof window !== "undefined" && window.speechSynthesis) {
      window.speechSynthesis.cancel();
      messages.filter(Boolean).forEach((m) => queueTomiUtterance(m, rate));
    }
  } catch (e) {
    // La voz es un extra, nunca debe romper la experiencia si falla.
  }
}

function queueTomiUtterance(message, rate = 1) {
  const utterance = new SpeechSynthesisUtterance(message.replace(/[🍅🍳💰❤️😎🤔👀🎉😅🥱👋✓✨]/gu, ""));
  utterance.lang = "es-ES";
  utterance.rate = rate;
  utterance.pitch = 1.35; // más dulce y tierna, tipo voz de niño (antes 1.15)
  const voice = pickTomiVoice();
  if (voice) utterance.voice = voice;
  window.speechSynthesis.speak(utterance);
}

/* Campanita breve y cálida cuando el temporizador termina. Sin archivos de
   audio externos: un par de tonos generados con Web Audio, muy discretos. */
function playTomiChime() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    [880, 1175].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = freq;
      const start = ctx.currentTime + i * 0.16;
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.18, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.35);
      osc.connect(gain).connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.4);
    });
  } catch (e) {
    // El sonido es un extra, nunca debe romper la experiencia si falla.
  }
}

function SpeakButton({ message, voiceEnabled }) {
  if (!voiceEnabled) return null;
  return (
    <button
      onClick={() => speakTomiMessage(message, true)}
      className="tomi-tap"
      style={{ fontSize: 13, opacity: 0.6, flexShrink: 0 }}
      aria-label="Escuchar a Tomi"
    >
      🔊
    </button>
  );
}

