/* Fotos reales para los ingredientes que ya las tienen (generadas una sola
   vez, no por IA en el momento — es una lista fija, no infinita como las
   recetas). Los ingredientes que aún no tienen foto siguen usando su emoji
   normalmente; ver ingredientPhoto() más abajo. */
const INGREDIENT_IMAGE_MAP = {
  huevo: "data:image/webp;base64,",
  cebolla: "data:image/webp;base64,",
  papa: "data:image/webp;base64,",
  arroz: "data:image/webp;base64,",
  tomate: "data:image/webp;base64,",
  frijoles: "data:image/webp;base64,",
  zanahoria: "data:image/webp;base64,",
  queso: "data:image/webp;base64,",
  pan: "data:image/webp;base64,",
  leche: "data:image/webp;base64,",
  coco: "data:image/webp;base64,",
  cilantro: "data:image/webp;base64,",
  pimiento: "data:image/webp;base64,",
  picante: "data:image/webp;base64,",
  pescado: "data:image/webp;base64,",
  aguacate: "data:image/webp;base64,",
  pasta: "data:image/webp;base64,",
  champinon: "data:image/webp;base64,",
  aceituna: "data:image/webp;base64,",
  ensalada: "data:image/webp;base64,",
  limon: "data:image/webp;base64,",
  pollo: "data:image/webp;base64,",
  ajo: "data:image/webp;base64,",
  atun: "data:image/webp;base64,",
};

function ingredientPhoto(id) {
  return INGREDIENT_IMAGE_MAP[id] || null;
}

/* Servicio simulado de análisis de imagen (versión anterior a esta capa).
   Ya NO se usa activamente — se conserva solo como referencia/respaldo
   para pruebas sin conexión, tal como pediste no eliminar código funcional
   sin razón técnica. El camino real hoy es analyzeIngredients(). */
function mockAnalyzeImage() {
  const roll = Math.random();
  if (roll < 0.62) {
    const ids = ["huevo", "papa", "arroz", "cebolla", "tomate", "frijoles"];
    return { outcome: "success", items: INGREDIENT_LIBRARY.filter((i) => ids.includes(i.id)) };
  }
  if (roll < 0.78) {
    const shuffled = [...INGREDIENT_LIBRARY].sort(() => 0.5 - Math.random());
    return { outcome: "success", items: shuffled.slice(0, 2) };
  }
  if (roll < 0.9) {
    return { outcome: "empty", items: [] };
  }
  return { outcome: "blurry", items: [] };
}

/* Resuelve el nombre que devuelve la IA contra la librería existente
   (para reusar emoji/id ya conocidos) y, si es un ingrediente nuevo,
   lo registra como personalizado — sin filtrar nada fuera de la lista fija. */
function resolveDetectedIngredient(rawName) {
  const normalized = rawName.trim().toLowerCase();
  const known = INGREDIENT_LIBRARY.find((it) => it.id === normalized || it.name.toLowerCase() === normalized);
  if (known) return known;
  const id = registerCustomIngredient(rawName, "🍽️");
  return ingredientMeta(id);
}

const VISION_PROMPT =
  "Eres el sistema de visión de una app de cocina llamada Tomi. Mira esta foto de una despensa, " +
  "nevera, alacena o mesa con ingredientes. Identifica únicamente los alimentos que puedas reconocer " +
  "con claridad en la imagen real — nunca inventes ingredientes que no se vean. " +
  "Usa nombres en español, en singular (ej. 'tomate', no 'tomates'). Si distingues una variedad " +
  "específica y visible (ej. 'cebolla morada'), consérvala tal cual en vez de generalizarla. " +
  "Responde ÚNICAMENTE con JSON válido, sin texto adicional, sin bloques de código, con esta forma exacta: " +
  '{"imageQuality":"clear"|"unclear","ingredients":[{"name":"string","confidence":0.0}]}. ' +
  'Usa "unclear" solo si la imagen está realmente demasiado oscura, borrosa, o si no se distingue nada útil. ' +
  "Si la imagen se ve bien pero no reconoces ningún alimento, deja ingredients como un arreglo vacío.";

/* Punto único de integración con la IA de visión real (Claude, con imagen).
   Contrato estable: imagen (data URL) → { outcome, items }.
   outcome puede ser "success" | "empty" | "blurry" | "error".
   El día que cambiemos de proveedor, esta es la única función a tocar —
   ninguna pantalla necesita cambiar. La generación de recetas (más adelante,
   generateRecipe(ingredients, preferences, time, budget)) es responsabilidad
   de otra función completamente separada; esta función NO decide recetas. */
/* ⚠️ VÍA TEMPORAL DE DESARROLLO — SOLO PARA PROBAR DENTRO DE CLAUDE.AI ⚠️
   Mientras no exista un backend real desplegado en /api/analyze-ingredients,
   esta bandera permite seguir probando el reconocimiento de ingredientes
   usando el mismo mecanismo sin API key que ya usa el cerebro culinario
   (generateRecipesWithAI) dentro de este entorno de Claude.ai.
   ELIMINAR O PONER EN false ANTES DE DESPLEGAR A PRODUCCIÓN. */
const VISION_DEV_FALLBACK_ENABLED = true;

/* Llama al backend seguro. La API key vive únicamente ahí, como variable
   de entorno del servidor (ver /api/analyze-ingredients.js). Esta función
   NO debe llamar directamente a Anthropic bajo ninguna circunstancia: si
   el endpoint no existe, no responde o falla, el fetch se rechaza o
   devuelve response.ok=false, y es analyzeIngredients() quien ya convierte
   eso en su estado "error" (no se maneja aquí para no duplicar lógica). */
async function requestVisionAnalysis(mediaType, base64Data) {
  const body = {
    model: "claude-sonnet-4-6",
    max_tokens: 700,
    messages: [
      {
        role: "user",
        content: [
          { type: "image", source: { type: "base64", media_type: mediaType, data: base64Data } },
          { type: "text", text: VISION_PROMPT },
        ],
      },
    ],
  };

  // 1) Vía de producción: backend propio y seguro. La API key vive solo ahí.
  try {
    const secure = await fetch("/api/analyze-ingredients", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (secure.ok) return secure;
  } catch (e) {
    // No hay backend desplegado en este entorno todavía: seguimos abajo.
  }

  // 2) ⚠️ Fallback TEMPORAL de desarrollo (ver VISION_DEV_FALLBACK_ENABLED
  //    arriba). Sin ninguna API key en el frontend: mismo mecanismo sin
  //    clave que ya usa el cerebro culinario dentro de Claude.ai.
  if (VISION_DEV_FALLBACK_ENABLED) {
    return fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
  }

  // Sin backend y sin fallback de desarrollo habilitado: dejamos que
  // analyzeIngredients() reciba una respuesta no-OK y pase a su estado "error".
  return { ok: false };
}

async function analyzeIngredients(imageDataUrl) {
  try {
    const match = /^data:([^;]+);base64,(.*)$/.exec(imageDataUrl || "");
    if (!match) return { outcome: "error", items: [] };
    const [, mediaType, base64Data] = match;

    const response = await requestVisionAnalysis(mediaType, base64Data);

    if (!response.ok) return { outcome: "error", items: [] };

    const data = await response.json();
    const textBlock = (data.content || []).find((b) => b.type === "text");
    if (!textBlock || !textBlock.text) return { outcome: "error", items: [] };

    let parsed;
    try {
      parsed = JSON.parse(textBlock.text.replace(/```json|```/g, "").trim());
    } catch (parseErr) {
      return { outcome: "error", items: [] };
    }

    if (parsed.imageQuality === "unclear") return { outcome: "blurry", items: [] };

    const rawIngredients = Array.isArray(parsed.ingredients) ? parsed.ingredients : [];
    const confident = rawIngredients.filter(
      (ing) => ing && typeof ing.name === "string" && ing.name.trim() && (ing.confidence === undefined || ing.confidence >= 0.35)
    );

    if (confident.length === 0) return { outcome: "empty", items: [] };

    const seen = new Set();
    const items = [];
    confident.forEach((ing) => {
      const meta = resolveDetectedIngredient(ing.name);
      if (!seen.has(meta.id)) {
        seen.add(meta.id);
        items.push(meta);
      }
    });

    return { outcome: "success", items };
  } catch (e) {
    return { outcome: "error", items: [] };
  }
}

/* Foto realista de una receta, generada bajo demanda con Gemini (Nano Banana)
   a través de nuestro propio backend seguro — la clave de Gemini vive solo
   ahí (ver /api/generate-recipe-image.js), nunca en este archivo.
   A diferencia de la visión de ingredientes, aquí NO hay un mecanismo sin
   clave dentro de Claude.ai (Gemini es un proveedor distinto de Anthropic),
   así que mientras no exista ese backend desplegado, esta función
   simplemente devuelve null y la tarjeta de receta se queda con su
   ícono/emoji de siempre — eso es el comportamiento esperado, no un error. */
async function requestRecipeImage(recipeName, description) {
  try {
    const response = await fetch("/api/generate-recipe-image", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ recipeName, description }),
    });
    if (!response.ok) return null;
    const data = await response.json();
    if (!data?.base64) return null;
    return `data:${data.mimeType || "image/png"};base64,${data.base64}`;
  } catch (e) {
    // Sin backend desplegado todavía, o sin conexión: nos quedamos con el ícono.
    return null;
  }
}

/* Registro de ingredientes escritos a mano por el usuario (ej. "brócoli"),
   que no están en la librería fija. Vive en memoria del módulo: alcanza
   para esta sesión y no rompe el resto de la app, que solo trabaja con ids. */
const CUSTOM_INGREDIENTS = {};
function registerCustomIngredient(rawName, emoji = "🍽️") {
  const name = rawName.trim();
  const id = name.toLowerCase();
  if (!id) return null;
  if (!INGREDIENT_LIBRARY.some((it) => it.id === id) && !CUSTOM_INGREDIENTS[id]) {
    CUSTOM_INGREDIENTS[id] = { id, name, emoji };
  }
  return id;
}

function ingredientMeta(id) {
  return INGREDIENT_LIBRARY.find((i) => i.id === id) || CUSTOM_INGREDIENTS[id] || { id, name: id, emoji: "🍽️" };
}

