function scoreRecipe(recipe, { pantryIds, timeLimit, budget, dislikedCategories, dislikedFoodIds, favoriteFoodIds = [] }) {
  if (recipe.categories.some((c) => dislikedCategories.includes(c))) return null;
  if (recipe.ingredients.some((i) => dislikedFoodIds.includes(i))) return null;

  const available = recipe.ingredients.filter((i) => pantryIds.includes(i));
  const missing = recipe.ingredients.filter((i) => !pantryIds.includes(i));

  let score = available.length * 12 - missing.length * 9;
  score += recipe.ingredients.filter((i) => favoriteFoodIds.includes(i)).length * 4;
  score -= Math.max(0, recipe.time - timeLimit) * 3;

  if (budget === "cero") {
    score += missing.length === 0 ? 20 : -15 * missing.length;
  } else if (budget === "poco" && missing.length > 3) {
    score -= 25;
  }
  score -= recipe.extraCost * 2;

  return { recipe, available, missing, score };
}

/* Motor de recomendación simulado — mismo contrato que usará la IA real más adelante. */
function recommendRecipes({ pantryIds, timeChoice, budget, dislikedCategories, dislikedFoodIds, favoriteFoodIds = [], jitter = false }) {
  const timeLimit = { "10": 10, "20": 20, "30": 30, mas: 999 }[timeChoice] ?? 999;
  const scored = DECIDE_RECIPES.map((r) =>
    scoreRecipe(r, { pantryIds, timeLimit, budget, dislikedCategories, dislikedFoodIds, favoriteFoodIds })
  )
    .filter(Boolean)
    .map((s) => (jitter ? { ...s, score: s.score + (Math.random() * 6 - 3) } : s))
    .sort((a, b) => b.score - a.score);

  return scored.slice(0, 3).map((s, idx) => ({
    ...s.recipe,
    availableIngredients: s.available,
    missingIngredients: s.missing,
    isRecommended: idx === 0,
  }));
}

function buildReason(recipe) {
  const bits = [];
  if (recipe.missingIngredients.length === 0) bits.push("puedes hacerla con lo que ya tienes");
  bits.push(recipe.time <= 15 ? "está lista en menos de 15 minutos" : `toma unos ${recipe.time} minutos`);
  return `Te recomiendo esta porque ${bits.join(" y ")}.`;
}

/* ============================================================
   CEREBRO CULINARIO — capa de IA para "No sé qué cocinar".
   Bloque independiente: DecideFlow solo llama a getCulinaryRecommendations().
   DECIDE_RECIPES, scoreRecipe, recommendRecipes y buildReason quedan
   intactas: siguen siendo el sistema existente y el respaldo real si la
   IA no está disponible o devuelve algo inválido.
   ============================================================ */

/* 1) Arma el contexto que recibe la IA, únicamente con datos que existen. */
function buildCulinaryContext({ availableIngredientItems, preferences, timeChoice, budget, cookHistory }) {
  const context = {};

  const ingredientNames = (availableIngredientItems || []).map((i) => i.name).filter(Boolean);
  if (ingredientNames.length > 0) context.availableIngredients = ingredientNames;

  if (preferences) {
    if (preferences.dislikedFoods?.length > 0) {
      context.dislikedFoods = preferences.dislikedFoods.map((id) => ingredientMeta(id).name);
    }
    if (preferences.favoriteFoods?.length > 0) {
      context.favoriteFoods = preferences.favoriteFoods.map((id) => ingredientMeta(id).name);
    }
    if (preferences.favoriteRecipes?.length > 0) {
      const names = preferences.favoriteRecipes.map((id) => findRecipeById(id)?.name).filter(Boolean);
      if (names.length > 0) context.favoriteRecipes = names;
    }
  }

  if (timeChoice) {
    const minutes = { "10": 10, "20": 20, "30": 30 }[timeChoice];
    if (minutes) context.availableTimeMinutes = minutes; // "mas" (sin límite) se omite a propósito
  }
  if (budget) context.budgetPreference = budget; // "cero" | "poco" | "flexible"

  if (cookHistory && cookHistory.length > 0) {
    const recent = cookHistory.slice(-5).map((h) => h.recipeName).filter(Boolean);
    if (recent.length > 0) context.recentlyCooked = recent;
  }

  return context;
}

const CULINARY_BRAIN_INSTRUCTIONS =
  "Eres el cerebro culinario de una app de cocina llamada Tomi. Con el siguiente contexto sobre una " +
  "persona, propone hasta 3 recetas reales, caseras y sencillas que realmente pueda preparar.\n\n" +
  "Reglas:\n" +
  "- Usa prioritariamente los ingredientes listados en availableIngredients.\n" +
  "- Nunca utilices como ingrediente principal algo listado en dislikedFoods.\n" +
  "- Si budgetPreference es \"cero\", prioriza recetas que no requieran comprar nada adicional.\n" +
  "- Si existe availableTimeMinutes, cada receta debe poder prepararse en ese tiempo o menos.\n" +
  "- Puedes incluir en una receta un ingrediente que no esté en availableIngredients si la receta " +
  "realmente lo necesita; no lo omitas ni asumas que la persona ya lo tiene, nosotros calcularemos " +
  "qué falta. Nunca inventes que algo está disponible si no aparece en el contexto.\n\n" +
  "Responde ÚNICAMENTE con JSON válido, sin texto adicional ni bloques de código, con esta forma exacta:\n" +
  '{"recipes":[{"title":"string","emoji":"un solo emoji de comida","description":"string breve",' +
  '"reason":"string breve explicando por qué se la recomiendas","timeMinutes":0,' +
  '"difficulty":"Fácil"|"Media"|"Difícil","extraCost":0,' +
  '"ingredients":[{"name":"string","quantity":"string opcional"}],' +
  '"steps":[{"title":"string","instruction":"string","tomiMessage":"string breve y cálido",' +
  '"durationSeconds":0,"requiresTimer":false}],' +
  '"substitutions":[{"ingredient":"string","alternatives":["string"]}]}]}';

/* 2) Llama al modelo. Mismo mecanismo ya usado en este entorno de Claude.ai:
   sin ninguna clave en el frontend. No es el mismo endpoint que el escáner
   (ese ahora vive detrás de /api/analyze-ingredients por decisión explícita
   anterior) — aquí no se envía ninguna imagen, solo texto/JSON. */
async function generateRecipesWithAI(context) {
  const promptText = `${CULINARY_BRAIN_INSTRUCTIONS}\n\nContexto:\n${JSON.stringify(context)}`;

  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 2000,
      messages: [{ role: "user", content: promptText }],
    }),
  });

  if (!response.ok) throw new Error("culinary_brain_http_error");

  const data = await response.json();
  const textBlock = (data.content || []).find((b) => b.type === "text");
  if (!textBlock || !textBlock.text) throw new Error("culinary_brain_empty_response");

  const cleaned = textBlock.text.replace(/```json|```/g, "").trim();
  const parsed = JSON.parse(cleaned); // si no es JSON válido, lanza — getCulinaryRecommendations lo atrapa

  return Array.isArray(parsed.recipes) ? parsed.recipes : [];
}

/* 3) Validación estricta: una receta sin ingredientes o sin pasos reales
   no sirve, aunque el JSON en sí sea válido. */
function validateAIRecipes(rawRecipes) {
  if (!Array.isArray(rawRecipes)) return [];
  return rawRecipes
    .filter((r) => {
      if (!r || typeof r !== "object") return false;
      if (typeof r.title !== "string" || !r.title.trim()) return false;
      if (typeof r.timeMinutes !== "number" || r.timeMinutes <= 0) return false;
      if (!Array.isArray(r.ingredients) || r.ingredients.length === 0) return false;
      if (!r.ingredients.every((ing) => ing && typeof ing.name === "string" && ing.name.trim())) return false;
      if (!Array.isArray(r.steps) || r.steps.length === 0) return false;
      if (!r.steps.every((s) => s && typeof s.instruction === "string" && s.instruction.trim())) return false;
      return true;
    })
    .slice(0, 3);
}

function slugifyRecipeTitle(text) {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "receta";
}

/* 4) Normaliza una receta validada al mismo formato que ya produce
   recommendRecipes(), para que RecipeCard/onViewRecipe no necesiten saber
   si la receta vino de la IA o del sistema existente. La disponibilidad de
   ingredientes SIEMPRE se calcula aquí, cruzando contra pantryIds — nunca
   se confía en lo que la IA haya asumido. Los campos aiSteps/aiReason/
   aiSubstitutions quedan guardados para conectar con CookFlow más adelante. */
function normalizeAIRecipe(raw, pantryIds, idx) {
  const resolvedIngredients = raw.ingredients.map((ing) => resolveDetectedIngredient(ing.name));
  const ingredientIds = [];
  resolvedIngredients.forEach((m) => {
    if (!ingredientIds.includes(m.id)) ingredientIds.push(m.id);
  });
  const availableIngredients = ingredientIds.filter((id) => pantryIds.includes(id));
  const missingIngredients = ingredientIds.filter((id) => !pantryIds.includes(id));

  const aiSteps = raw.steps.map((s, i) => ({
    id: i + 1,
    title: typeof s.title === "string" && s.title.trim() ? s.title : `Paso ${i + 1}`,
    instruction: s.instruction,
    tomiMessage: typeof s.tomiMessage === "string" && s.tomiMessage.trim() ? s.tomiMessage : "Vamos bien, sigamos con este paso.",
    duration: typeof s.durationSeconds === "number" && s.durationSeconds > 0 ? s.durationSeconds : null,
    requiresTimer: !!s.requiresTimer,
    requiresConfirmation: true,
  }));

  const aiSubstitutions = Array.isArray(raw.substitutions)
    ? raw.substitutions
        .filter((s) => s && typeof s.ingredient === "string" && Array.isArray(s.alternatives))
        .map((s) => ({ ingredient: s.ingredient, alternatives: s.alternatives.filter((a) => typeof a === "string") }))
    : [];

  const missingBasedCost = missingIngredients.length === 0 ? 0 : 1;

  return {
    id: `ai_${slugifyRecipeTitle(raw.title)}_${idx}`,
    name: raw.title,
    emoji: typeof raw.emoji === "string" && raw.emoji.trim() ? raw.emoji : "🍽️",
    time: raw.timeMinutes,
    difficulty: ["Fácil", "Media", "Difícil"].includes(raw.difficulty) ? raw.difficulty : "Fácil",
    ingredients: ingredientIds,
    extraCost: typeof raw.extraCost === "number" ? Math.max(0, Math.min(3, Math.round(raw.extraCost))) : missingBasedCost,
    categories: [],
    description: typeof raw.description === "string" ? raw.description : "",
    availableIngredients,
    missingIngredients,
    isRecommended: idx === 0,
    source: "ai",
    aiReason: typeof raw.reason === "string" ? raw.reason : "",
    aiSteps,
    aiSubstitutions,
  };
}

/* 5) Única función pública del cerebro. DecideFlow no necesita saber nada
   de lo anterior: le pasa el mismo tipo de datos que ya usaba para
   recommendRecipes() y recibe de vuelta una lista de recetas lista para
   RecipeCard. Si la IA falla, no responde, o su resultado no pasa la
   validación, se usa automáticamente recommendRecipes() como respaldo. */
async function getCulinaryRecommendations({
  pantryIds,
  availableIngredientItems,
  preferences,
  timeChoice,
  budget,
  dislikedCategories,
  dislikedFoodIds,
  favoriteFoodIds,
  cookHistory,
  jitter = false,
}) {
  try {
    const context = buildCulinaryContext({ availableIngredientItems, preferences, timeChoice, budget, cookHistory });
    const rawRecipes = await generateRecipesWithAI(context);
    const validRecipes = validateAIRecipes(rawRecipes);
    if (validRecipes.length === 0) throw new Error("culinary_brain_invalid_result");
    return validRecipes.map((r, idx) => normalizeAIRecipe(r, pantryIds, idx));
  } catch (e) {
    return recommendRecipes({ pantryIds, timeChoice, budget, dislikedCategories, dislikedFoodIds, favoriteFoodIds, jitter });
  }
}

