function genericSteps(recipe) {
  const main = recipe.ingredients[0] ? ingredientMeta(recipe.ingredients[0]) : { emoji: "🍽️" };
  const names = recipe.ingredients.map((i) => ingredientMeta(i).name.toLowerCase()).join(", ");
  const hasOnion = recipe.ingredients.includes("cebolla");
  const prepMessage = hasOnion
    ? "Tener todo listo antes de empezar hace todo más fácil. Ah, y si la cebolla te hace llorar un poquito… no le voy a decir a nadie. 😉"
    : "Tener todo listo antes de empezar hace todo más fácil.";
  return [
    { id: 1, title: "Prepara los ingredientes", instruction: `Lava y corta: ${names}.`, image: main.emoji, tomiMessage: prepMessage, duration: null, requiresTimer: false, requiresConfirmation: true, confirmLabel: "✓ Ya lo hice" },
    { id: 2, title: "Cocina todo junto", instruction: "Cocina los ingredientes en la sartén u olla a fuego medio.", image: "🍳", tomiMessage: "Yo vigilo el tiempo por ti. 😎", duration: Math.max(180, (recipe.time - 5) * 60), requiresTimer: true, requiresConfirmation: true, confirmLabel: "🔥 Ya está cocinándose" },
    { id: 3, title: "Ajusta el sabor", instruction: "Prueba y ajusta la sal a tu gusto.", image: "🧂", tomiMessage: "Confía en tu paladar, tú conoces mejor tus gustos.", duration: null, requiresTimer: false, requiresConfirmation: true, confirmLabel: "✓ Listo" },
    { id: 4, title: "Sirve y disfruta", instruction: "Sirve caliente y ¡a disfrutar!", image: "🍽️", tomiMessage: "¡Lo lograste! Estoy orgulloso de ti. 🍅", duration: null, requiresTimer: false, requiresConfirmation: true, confirmLabel: "✓ Ya está listo" },
  ];
}

/* Contrato estable: hoy arma el detalle desde datos mock, mañana puede
   venir directo de una receta generada por IA sin cambiar la interfaz. */
function getRecipeDetails(recipe) {
  const custom = RECIPE_DETAILS[recipe.id];
  return {
    id: recipe.id,
    name: recipe.name,
    image: recipe.emoji,
    servings: custom ? custom.servings : 2,
    totalTime: recipe.time,
    extraCost: recipe.extraCost,
    difficulty: recipe.difficulty,
    equipment: custom ? custom.equipment : "Solo necesitas utensilios básicos: sartén, cuchillo y tabla.",
    description: recipe.description,
    coreIngredients: recipe.ingredients,
    extraIngredients: custom ? custom.extraIngredients : ["sal", "aceite"],
    missingIngredients: recipe.missingIngredients || [],
    steps: recipe.steps || (custom ? custom.steps : genericSteps(recipe)),
  };
}

/* Estructura de precio preparada para una fuente real más adelante.
   Por ahora nunca se muestra un número: solo priceSource:"mock". */
function mockPriceRecord(id, quantity = 1, unit = "unidad") {
  const m = ingredientMeta(id);
  return { ingredientId: id, name: m.name, quantity, unit, estimatedCost: null, priceSource: "mock", lastUpdated: null };
}

function savingsCategoryFor(missingCount, extraCost) {
  if (missingCount === 0) return { id: "cero", emoji: "💚", label: "$0 extra" };
  if (missingCount === 1 && extraCost <= 1) return { id: "muy_bajo", emoji: "🟢", label: "Muy bajo" };
  if (missingCount <= 2) return { id: "bajo", emoji: "🟡", label: "Bajo" };
  return { id: "moderado", emoji: "🟠", label: "Moderado" };
}

/* Motor del Modo Ahorro, separado de la interfaz para poder
   reemplazarlo luego por precios reales / IA sin tocar las pantallas. */
function calculateSavingsOptions({ pantryIds, budgetMode, dislikedFoodIds, favoriteFoodIds = [] }) {
  const scored = DECIDE_RECIPES.filter((r) => !r.ingredients.some((i) => dislikedFoodIds.includes(i)))
    .map((r) => {
      const available = r.ingredients.filter((i) => pantryIds.includes(i));
      const missing = r.ingredients.filter((i) => !pantryIds.includes(i));
      return { recipe: r, available, missing };
    })
    .filter((s) => (budgetMode === "cero" ? s.missing.length === 0 : true))
    .map((s) => ({
      ...s,
      score:
        s.available.length * 10 -
        s.missing.length * 8 +
        (s.missing.length === 0 ? 15 : 0) -
        s.recipe.extraCost * 2 +
        s.recipe.ingredients.filter((i) => favoriteFoodIds.includes(i)).length * 3,
    }))
    .sort((a, b) => b.score - a.score);

  return scored.slice(0, 3).map((s, idx) => ({
    ...s.recipe,
    availableIngredients: s.available,
    missingIngredients: s.missing,
    usagePct: Math.round((s.available.length / s.recipe.ingredients.length) * 100),
    savingsCategory: savingsCategoryFor(s.missing.length, s.recipe.extraCost),
    estimatedExtraCost: s.missing.length === 0 ? 0 : s.recipe.extraCost,
    servings: 2,
    isRecommended: idx === 0,
  }));
}

function buildSavingsReason(option) {
  if (option.missingIngredients.length === 0) {
    return "Te recomiendo esta porque no necesitas comprar nada y aprovecha varios ingredientes que ya tienes.";
  }
  const n = option.missingIngredients.length;
  return `Te recomiendo esta porque solo te falta ${n === 1 ? "un ingrediente" : `${n} ingredientes`} y aprovechas casi todo lo que ya tienes.`;
}

