/* userPreferences: lo que el usuario dijo explícitamente.
   userHistory: usamos cookHistory (ya existente) como fuente única —
   no duplicamos esa información aquí.
   userInsights: se derivan siempre en caliente a partir de preferencias +
   historial, nunca se inventan ni se guardan como hechos fijos. */
const MOCK_USER_PREFERENCES = {
  name: "",
  email: "",
  wantsNewsletter: false,
  favoriteFoods: ["huevo", "papa", "arroz"],
  dislikedFoods: [],
  favoriteRecipes: [],
  cookingTimePreference: "20",
  budgetPreference: "cero",
  dietaryPreferences: [],
  frequentIngredients: ["huevo", "arroz"],
  voiceEnabled: true,
};

function getUserPreferences(userMemory) {
  return userMemory.preferences;
}

function addFavoriteFood(prefs, id) {
  return prefs.favoriteFoods.includes(id) ? prefs : { ...prefs, favoriteFoods: [...prefs.favoriteFoods, id] };
}
function removeFavoriteFood(prefs, id) {
  return { ...prefs, favoriteFoods: prefs.favoriteFoods.filter((x) => x !== id) };
}
function addDislikedFood(prefs, id) {
  return prefs.dislikedFoods.includes(id) ? prefs : { ...prefs, dislikedFoods: [...prefs.dislikedFoods, id] };
}
function removeDislikedFood(prefs, id) {
  return { ...prefs, dislikedFoods: prefs.dislikedFoods.filter((x) => x !== id) };
}
function addFavoriteRecipe(prefs, id) {
  return prefs.favoriteRecipes.includes(id) ? prefs : { ...prefs, favoriteRecipes: [...prefs.favoriteRecipes, id] };
}
function removeFavoriteRecipe(prefs, id) {
  return { ...prefs, favoriteRecipes: prefs.favoriteRecipes.filter((x) => x !== id) };
}
function updateCookingTimePreference(prefs, value) {
  return { ...prefs, cookingTimePreference: value };
}
function updateBudgetPreference(prefs, value) {
  return { ...prefs, budgetPreference: value };
}
function toggleVoiceEnabled(prefs) {
  return { ...prefs, voiceEnabled: !prefs.voiceEnabled };
}
function clearUserMemory() {
  return { favoriteFoods: [], dislikedFoods: [], favoriteRecipes: [], cookingTimePreference: null, budgetPreference: null, dietaryPreferences: [], frequentIngredients: [], voiceEnabled: true };
}

/* Aprendizajes derivados: solo a partir de preferencias explícitas y
   comportamiento registrado (cookHistory). Nunca inventa características
   personales ni información sensible. */
function getUserInsights({ preferences, cookHistory }) {
  const statements = [];
  const quickCount = cookHistory.filter((h) => h.totalTime <= 20).length;
  const quickRecipePreference = (cookHistory.length > 0 && quickCount / cookHistory.length >= 0.5) || ["10", "20"].includes(preferences.cookingTimePreference);
  if (quickRecipePreference) statements.push("Te gustan las recetas rápidas.");

  const zeroCount = cookHistory.filter((h) => h.extraCost === 0).length;
  const savingsPreference = (cookHistory.length > 0 && zeroCount / cookHistory.length >= 0.5) || preferences.budgetPreference === "cero";
  if (savingsPreference) statements.push("Prefieres aprovechar primero lo que ya tienes.");

  if (preferences.favoriteFoods.length > 0) {
    const names = preferences.favoriteFoods.map((id) => ingredientMeta(id).name.toLowerCase());
    statements.push(`Te gustan las recetas con ${names.slice(0, 2).join(" y ")}.`);
  }
  if (preferences.dislikedFoods.length > 0) {
    const names = preferences.dislikedFoods.map((id) => ingredientMeta(id).name.toLowerCase());
    statements.push(`No sueles elegir recetas con ${names.join(", ")}.`);
  }
  if (cookHistory.length >= 3) statements.push(`Ya cocinaste ${cookHistory.length} recetas junto a Tomi.`);

  return { statements: statements.slice(0, 5), quickRecipePreference, savingsPreference };
}

/* Reconstruye el objeto de receta que consumen Decidir/Ahorro/Cocinar
   a partir de un id guardado (favorito o historial), cruzándolo con la
   despensa actual. */
/* Busca una receta por id en TODAS las fuentes (decidir, categorías y países),
   para que un favorito funcione sin importar de dónde vino. */
function findRecipeById(id) {
  return (
    DECIDE_RECIPES.find((r) => r.id === id) ||
    CATEGORY_RECIPES.find((r) => r.id === id) ||
    COUNTRY_RECIPES.find((r) => r.id === id) ||
    null
  );
}

/* Platos con foto real que se muestran en Inicio mientras la persona
   todavía no ha guardado favoritos. */
const HOME_SUGGESTED_RECIPE_IDS = [
  "co_bandeja_paisa",
  "ve_pabellon_criollo",
  "co_ajiaco_santafereno",
  "ve_arepa_reina_pepiada",
  "co_arepa_de_huevo",
  "ve_tequenos",
];

function buildRecipeSummaryFromId(id, pantryIds) {
  const base = findRecipeById(id);
  if (!base) return null;
  const available = base.ingredients.filter((i) => pantryIds.includes(i));
  const missing = base.ingredients.filter((i) => !pantryIds.includes(i));
  return { ...base, availableIngredients: available, missingIngredients: missing, isRecommended: false };
}

function daysAgoLabel(iso) {
  const days = Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 86400000));
  if (days === 0) return "Preparada hoy";
  if (days === 1) return "Preparada ayer";
  return `Preparada hace ${days} días`;
}

