/* ---------------- Onboarding ---------------- */

function OnboardingScreen({ obStep, setObStep, obData, setObData, dislikedFoods, onUpdatePreferences, onFinish, onBackToWelcome }) {
  const [dislikeReaction, setDislikeReaction] = useState(null);
  const DISLIKE_ADD_PHRASES = ["¡Entendido! Lo tendré en cuenta. 🍅", "Anotado. Intentaré no ponértelo en las recetas. 😊"];

  const toggleInArray = (key, id, single = false) => {
    setObData((prev) => {
      if (single) return { ...prev, [key]: prev[key] === id ? null : id };
      const arr = prev[key];
      const next = arr.includes(id) ? arr.filter((x) => x !== id) : [...arr, id];
      return { ...prev, [key]: next };
    });
  };

  const toggleDislike = (id) => {
    const isDisliked = dislikedFoods.includes(id);
    onUpdatePreferences((p) => (isDisliked ? removeDislikedFood(p, id) : addDislikedFood(p, id)));
    if (isDisliked) {
      setDislikeReaction("¡Listo! Ya no lo tengo en tu lista de cosas a evitar.");
    } else {
      setDislikeReaction(DISLIKE_ADD_PHRASES[Math.floor(Math.random() * DISLIKE_ADD_PHRASES.length)]);
    }
    setTimeout(() => setDislikeReaction(null), 1800);
  };

  const canContinue =
    obStep === 0 ? obData.goals.length > 0 :
    obStep === 1 ? !!obData.time :
    obStep === 2 ? !!obData.savings :
    true;

  const handleNext = () => {
    if (obStep < 3) setObStep(obStep + 1);
    else onFinish();
  };

  const handleBack = () => {
    if (obStep === 0) onBackToWelcome();
    else setObStep(obStep - 1);
  };

  return (
    <div className="tomi-bg-cream h-full flex flex-col">
      <ScreenHeader onBack={handleBack} step={obStep} total={4} />

      <div className="flex-1 overflow-y-auto tomi-scroll px-6 pb-4">
        {obStep === 0 && (
          <>
            <h2 className="tomi-display tomi-text-ink" style={{ fontSize: 22, fontWeight: 700 }}>¿Qué quieres conseguir?</h2>
            <p className="tomi-text-ink-soft" style={{ marginTop: 6, marginBottom: 18, fontSize: 14 }}>Puedes elegir varias opciones.</p>
            <div className="flex flex-col gap-3">
              {GOALS.map((g) => (
                <Chip key={g.id} active={obData.goals.includes(g.id)} onClick={() => toggleInArray("goals", g.id)}>
                  <span style={{ marginRight: 8 }}>{g.emoji}</span>
                  <span className="tomi-display" style={{ fontWeight: 600 }}>{g.label}</span>
                </Chip>
              ))}
            </div>
          </>
        )}

        {obStep === 1 && (
          <>
            <h2 className="tomi-display tomi-text-ink" style={{ fontSize: 22, fontWeight: 700 }}>¿Cuánto tiempo tienes normalmente para cocinar?</h2>
            <div className="flex flex-col gap-3" style={{ marginTop: 18 }}>
              {TIME_OPTIONS.map((t) => (
                <Chip key={t.id} active={obData.time === t.id} onClick={() => toggleInArray("time", t.id, true)}>
                  <span className="tomi-display" style={{ fontWeight: 600 }}>⏱️ {t.label}</span>
                </Chip>
              ))}
            </div>
          </>
        )}

        {obStep === 2 && (
          <>
            <h2 className="tomi-display tomi-text-ink" style={{ fontSize: 22, fontWeight: 700 }}>¿Qué tan importante es ahorrar?</h2>
            <div className="flex flex-col gap-3" style={{ marginTop: 18 }}>
              {SAVINGS_OPTIONS.map((s) => (
                <Chip key={s.id} active={obData.savings === s.id} onClick={() => toggleInArray("savings", s.id, true)}>
                  <span style={{ marginRight: 8 }}>{s.emoji}</span>
                  <span className="tomi-display" style={{ fontWeight: 600 }}>{s.label}</span>
                </Chip>
              ))}
            </div>
          </>
        )}

        {obStep === 3 && (
          <>
            <h2 className="tomi-display tomi-text-ink" style={{ fontSize: 22, fontWeight: 700 }}>Hay alimentos que no te gustan, ¿verdad?</h2>
            <p className="tomi-text-ink-soft" style={{ marginTop: 6, marginBottom: 18, fontSize: 14 }}>
              Cuéntame cuáles y procuraré no recomendártelos.
            </p>
            <div className="grid grid-cols-2 gap-3">
              {FOOD_OPTIONS.map((f) => (
                <Chip key={f.id} active={dislikedFoods.includes(f.id)} onClick={() => toggleDislike(f.id)}>
                  <span style={{ marginRight: 6 }}>{f.emoji}</span>
                  <span style={{ fontSize: 14, fontWeight: 600 }}>{f.label}</span>
                </Chip>
              ))}
            </div>

            <p className="tomi-text-ink-soft" style={{ fontSize: 13, fontWeight: 600, marginTop: 20, marginBottom: 6 }}>¿Hay alguno más?</p>
            <IngredientTagList
              ids={dislikedFoods.filter((id) => !FOOD_OPTIONS.some((f) => f.id === id))}
              onRemove={toggleDislike}
              emptyText=""
            />
            <AddIngredientInline
              excludeIds={dislikedFoods}
              placeholder="Escribe algo que no te guste…"
              emoji="🚫"
              onAdd={(id) => {
                onUpdatePreferences((p) => addDislikedFood(p, id));
                setDislikeReaction(DISLIKE_ADD_PHRASES[Math.floor(Math.random() * DISLIKE_ADD_PHRASES.length)]);
                setTimeout(() => setDislikeReaction(null), 1800);
              }}
            />
            {dislikeReaction && (
              <p className="tomi-text-tomato-deep tomi-pop-in" style={{ fontSize: 13, fontWeight: 700, marginTop: 10 }}>{dislikeReaction}</p>
            )}
          </>
        )}
      </div>

      <div className="px-6 pb-8 pt-2">
        <PrimaryButton onClick={handleNext} disabled={!canContinue}>
          {obStep === 3 ? "Guardar mis preferencias" : "Continuar"}
        </PrimaryButton>
      </div>
    </div>
  );
}

